import React, { useCallback } from "react";
import { TableHeader, TableRow, ArrowButton } from './TableHead.Styled';

const TableHead = ({ columns, sortConfig, setSortConfig }) => {

    const handleSort = useCallback((column) => {
        if (column === "SNo") return;
        let direction = "asc";
        if (sortConfig?.key === column && sortConfig?.direction === "asc") {
            direction = "desc";
        }else{
            
        }
        setSortConfig({ key: column, direction });
    }, [sortConfig]);

    return (
        <thead>
            <TableRow>
                {columns?.map((column, index) => {
                    const arrowIcon = sortConfig?.key === column?.label ?
                        sortConfig?.direction === "asc" ? "fas fa-arrow-up" : "fas fa-arrow-down" : "";
                    return (<TableHeader key={index}>
                        {column?.value}{" "}
                        {
                            <ArrowButton onClick={() => handleSort(column?.label)}> {column?.sort+ " "}<i className={arrowIcon}></i></ArrowButton>
                        }
                    </TableHeader>)
                })}
            </TableRow>
        </thead>
    )
}

export default React.memo(TableHead);
